### 2. Password Validation Utility
```javascript
// utils/validation.js
export function validatePassword(password) {
  const minLength = 8;
  const hasUpperCase = /[A-Z]/.test(password);
  const hasLowerCase = /[a-z]/.test(password);
  const hasNumber = /[0-9]/.test(password);
  const hasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]+/.test(password);

  const errors = [];
  if (password.length < minLength) errors.push(`Password must be at least ${minLength} characters`);
  if (!hasUpperCase) errors.push("Password must contain an uppercase letter");
  if (!hasLowerCase) errors.push("Password must contain a lowercase letter");
  if (!hasNumber) errors.push("Password must contain a number");
  if (!hasSpecialChar) errors.push("Password must contain a special character");

  return {
    isValid: errors.length === 0,
    errors
  };
}
```

### 3. Email/Password Registration Implementation
```javascript
const handleEmailSignUp = async (e) => {
  e.preventDefault();
  setMessage({ type: "", text: "" });

  // Validate form inputs
  if (!formData.email || !formData.password || !formData.confirmPassword) {
    return setMessage({ type: "error", text: "All fields are required" });
  }

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(formData.email)) {
    return setMessage({ type: "error", text: "Please enter a valid email address" });
  }

  // Validate password
  const { isValid, errors } = validatePassword(formData.password);
  if (!isValid) {
    return setMessage({ type: "error", text: errors.join(". ") });
  }

  // Check if passwords match
  if (formData.password !== formData.confirmPassword) {
    return setMessage({ type: "error", text: "Passwords do not match" });
  }

  setLoading(true);

  try {
    const { data, error } = await supabase.auth.signUp({
      email: formData.email,
      password: formData.password,
      options: {
        emailRedirectTo: `${window.location.origin}/auth/callback`
      }
    });

    if (error) throw error;

    setMessage({ 
      type: "success", 
      text: "Registration successful! Please check your email to confirm your account." 
    });

    // Clear form
    setFormData({ email: "", password: "", confirmPassword: "" });
  } catch (error) {
    setMessage({ type: "error", text: error.message || "An error occurred during registration" });
  } finally {
    setLoading(false);
  }
};
```

