### Add API Endpoint to Fetch Waitlist by ID
5. Create a new API endpoint at `app/api/waitlists/[id]/route.js`:

```jsx
import { createRouteHandlerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'
import { NextResponse } from 'next/server'

export async function GET(request, { params }) {
  const supabase = createRouteHandlerClient({ cookies })

  // Verify user is authenticated
  const { data: { session } } = await supabase.auth.getSession()

  if (!session) {
    return NextResponse.json(
      { error: 'Authentication required' },
      { status: 401 }
    )
  }

  const userId = session.user.id
  const { id } = params

  if (!id) {
    return NextResponse.json(
      { error: 'Waitlist ID is required' },
      { status: 400 }
    )
  }

  // Fetch the waitlist data
  const { data, error } = await supabase
    .from('waitlists')
    .select('*')
    .eq('id', id)
    .eq('owner_id', userId)
    .single()

  if (error) {
    console.error('Error fetching waitlist:', error)
    return NextResponse.json(
      { error: 'Failed to fetch waitlist' },
      { status: 500 }
    )
  }

  if (!data) {
    return NextResponse.json(
      { error: 'Waitlist not found or you do not have permission to access it' },
      { status: 404 }
    )
  }

  return NextResponse.json(data)
}
```

