**Virtual Scrolling Hook (useVirtualScrolling.js):**
```javascript
// Optimized for lists >100 items with 35px item height
const ITEM_HEIGHT = 35;
const CONTAINER_HEIGHT = 384; // max-h-96 = 24rem = 384px
const VISIBLE_ITEMS = Math.ceil(CONTAINER_HEIGHT / ITEM_HEIGHT) + 2; // +2 for buffer

export const useVirtualScrolling = (items, containerRef) => {
  const [scrollTop, setScrollTop] = useState(0);
  const [visibleRange, setVisibleRange] = useState({ start: 0, end: VISIBLE_ITEMS });

  // Calculate visible items based on scroll position
  const startIndex = Math.floor(scrollTop / ITEM_HEIGHT);
  const endIndex = Math.min(startIndex + VISIBLE_ITEMS, items.length);

  return {
    visibleItems: items.slice(startIndex, endIndex),
    totalHeight: items.length * ITEM_HEIGHT,
    offsetY: startIndex * ITEM_HEIGHT
  };
};
```

