```javascript
// utils/subscription.js
const hasValidSubscription = (user) => {
  if (!user.has_access) return false;

  // Lifetime access (Hacker plan)
  if (!user.access_expires_at) return true;

  // Check if Pro plan hasn't expired
  return new Date() < new Date(user.access_expires_at);
};

const getSubscriptionDetails = (user) => {
  if (!user.has_access) return { type: 'none', status: 'inactive' };

  const isHacker = !user.access_expires_at;
  const isExpired = user.access_expires_at && new Date() > new Date(user.access_expires_at);

  return {
    type: isHacker ? 'hacker' : 'pro',
    status: isExpired ? 'expired' : 'active',
    expiresAt: user.access_expires_at
  };
};

const getRemainingDays = (user) => {
  if (!user.access_expires_at) return null; // Lifetime access

  const now = new Date();
  const expiresAt = new Date(user.access_expires_at);
  const diffTime = expiresAt - now;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};
