### Advanced Environment Detection Patterns
```javascript
// Enhanced environment detection with hostname validation
const getEnvironmentFromHostname = () => {
  if (typeof window === 'undefined') return 'server';

  const hostname = window.location.hostname;
  const patterns = {
    development: ['localhost', '127.0.0.1', '0.0.0.0'],
    staging: ['staging.vibe-list.com', 'dev.vibe-list.com'],
    production: ['vibe-list.com', 'www.vibe-list.com']
  };

  for (const [env, hosts] of Object.entries(patterns)) {
    if (hosts.some(host => hostname.includes(host))) return env;
  }
  return 'unknown';
};
```

### Error Handling & Validation
```javascript
// Add robust error handling to getBaseUrl()
const validateUrl = (url) => {
  try {
    new URL(url);
    return true;
  } catch {
    console.warn(`Invalid URL detected: ${url}`);
    return false;
  }
};

// Enhanced getBaseUrl with validation
const getBaseUrl = () => {
  const envUrl = process.env.NEXT_PUBLIC_URL;

  if (envUrl && validateUrl(envUrl)) {
    return envUrl.replace(/\/$/, ''); // Remove trailing slash
  }

  // Client-side fallback with validation
  if (typeof window !== 'undefined') {
    const origin = window.location.origin;
    return validateUrl(origin) ? origin : 'http://localhost:3000';
  }

  // Server-side fallback
  return isDevelopment() ? 'http://localhost:3000' : 'https://vibe-list.com';
};
```

